-- Run while connected to tampere_transport.
-- Use transport_user, or an administrator allowed to SET ROLE.

BEGIN;

SET LOCAL ROLE transport_user;

CREATE TABLE public.pipeline_runs (
    -- Generated by Python, so the same ID can also appear in logs.
    run_id UUID PRIMARY KEY,

    started_at_utc TIMESTAMPTZ NOT NULL,
    finished_at_utc TIMESTAMPTZ,

    status TEXT NOT NULL DEFAULT 'running',

    -- The stage being executed, or the stage where failure occurred.
    stage TEXT NOT NULL DEFAULT 'configuration',

    -- Unknown until a raw snapshot has been saved.
    source_file TEXT,

    -- Unknown until validation or loading completes.
    records_validated INTEGER,
    records_inserted INTEGER,
    duplicates_skipped INTEGER,

    -- Store the exception class, rather than raw error text.
    error_type TEXT,

    CONSTRAINT chk_pipeline_run_status CHECK (
        status IN ('running', 'succeeded', 'failed')
    ),

    CONSTRAINT chk_pipeline_run_stage CHECK (
        stage IN (
            'configuration',
            'collection',
            'saving',
            'validation',
            'loading',
            'complete'
        )
    ),

    CONSTRAINT chk_pipeline_run_times CHECK (
        finished_at_utc IS NULL
        OR finished_at_utc >= started_at_utc
    ),

    CONSTRAINT chk_pipeline_run_finished CHECK (
        (
            status = 'running'
            AND finished_at_utc IS NULL
        )
        OR
        (
            status IN ('succeeded', 'failed')
            AND finished_at_utc IS NOT NULL
        )
    ),

    CONSTRAINT chk_pipeline_run_counts CHECK (
        (records_validated IS NULL OR records_validated >= 0)
        AND (records_inserted IS NULL OR records_inserted >= 0)
        AND (duplicates_skipped IS NULL OR duplicates_skipped >= 0)
    ),

    CONSTRAINT chk_pipeline_run_success CHECK (
        status <> 'succeeded'
        OR (
            stage = 'complete'
            AND source_file IS NOT NULL
            AND records_validated IS NOT NULL
            AND records_inserted IS NOT NULL
            AND duplicates_skipped IS NOT NULL
            AND records_validated =
                records_inserted + duplicates_skipped
            AND error_type IS NULL
        )
    )
);

CREATE INDEX idx_pipeline_runs_started_at
    ON public.pipeline_runs (started_at_utc DESC);

COMMIT;